"""Regenerate the generated files under docs/architecture/.

Run via `make docs`. Executes inside the backend container, where /app is the
backend dir and /docs is the repo's docs/ mount. Reads SQLAlchemy metadata and
the FastAPI route table — no database connection is needed.

Outputs: db/schema.md (DDL), db/er-diagram.md (Mermaid), api/routes.md
(endpoint inventory) — grouped by domain under docs/architecture/.
"""

import argparse
import importlib
import pkgutil
import sys
from datetime import date, datetime
from decimal import Decimal
from pathlib import Path
from uuid import UUID

from sqlalchemy.dialects import postgresql
from sqlalchemy.schema import CreateIndex, CreateTable
from sqlalchemy.sql import sqltypes

# The script lives in backend/scripts/docs/ — put the backend dir on sys.path
# so `import app.*` works regardless of the invocation cwd.
sys.path.insert(0, str(Path(__file__).resolve().parents[2]))

import app.features  # noqa: E402
from app.core.db import Base  # noqa: E402

MD_HEADER = (
    "<!-- GENERATED by `make docs` (backend/scripts/docs/generate.py). Do not edit by hand. -->\n"
)


def _import_feature_models() -> None:
    """Import each feature's models module so tables register on Base.metadata."""
    for mod in pkgutil.iter_modules(app.features.__path__):
        name = f"app.features.{mod.name}.models"
        try:
            importlib.import_module(name)
        except ModuleNotFoundError as exc:
            if exc.name != name:  # models.py exists but one of its imports failed
                raise


def _mermaid_type(col_type: sqltypes.TypeEngine) -> str:
    """Map a column type to a short Mermaid-safe type name."""
    if isinstance(col_type, sqltypes.Text):
        return "text"
    try:
        py_type = col_type.python_type
    except NotImplementedError:
        py_type = None
    return {
        int: "int",
        str: "string",
        bool: "bool",
        float: "float",
        Decimal: "decimal",
        datetime: "datetime",
        date: "date",
        dict: "json",
        bytes: "blob",
        UUID: "uuid",
    }.get(py_type, type(col_type).__name__.lower())


def _write(out_dir: Path, rel: str, body: str) -> Path:
    path = out_dir / rel
    path.parent.mkdir(parents=True, exist_ok=True)
    # The H1 must lead the file: MkDocs only derives a page's nav title from
    # an H1 when nothing (not even an HTML comment) precedes it. Keep the
    # generated-marker comment on line 3 instead of line 1.
    title, _, rest = body.partition("\n")
    path.write_text(f"{title}\n\n{MD_HEADER}\n{rest.lstrip()}")
    return path


def generate_schema(out_dir: Path) -> Path:
    """Emit db/schema.md — the DDL implied by the models (Postgres dialect)."""
    dialect = postgresql.dialect()
    statements = []
    for table in Base.metadata.sorted_tables:
        statements.append(str(CreateTable(table).compile(dialect=dialect)).rstrip() + ";")
        statements.extend(
            str(CreateIndex(index).compile(dialect=dialect)).rstrip() + ";"
            for index in table.indexes
        )
    body = "# Database schema\n\n```sql\n" + "\n\n".join(statements) + "\n```\n"
    return _write(out_dir, "db/schema.md", body)


def generate_erd(out_dir: Path) -> Path:
    """Emit db/er-diagram.md — a Mermaid erDiagram of tables and FK relationships."""
    lines = ["```mermaid", "erDiagram"]
    for table in Base.metadata.sorted_tables:
        lines.append(f"    {table.name} {{")
        for col in table.columns:
            keys = ",".join(
                k for k, flag in (("PK", col.primary_key), ("FK", bool(col.foreign_keys))) if flag
            )
            lines.append(f"        {_mermaid_type(col.type)} {col.name} {keys}".rstrip())
        lines.append("    }")
    for table in Base.metadata.sorted_tables:
        for fk in table.foreign_keys:
            # One parent per child row (|o if the FK is nullable);
            # a parent has zero-or-many children.
            left = "|o" if fk.parent.nullable else "||"
            lines.append(
                f'    {fk.column.table.name} {left}--o{{ {table.name} : "{fk.parent.name}"'
            )
    lines.append("```")
    body = "# Entity-relationship diagram\n\n" + "\n".join(lines) + "\n"
    return _write(out_dir, "db/er-diagram.md", body)


# OpenAPI path-item keys that aren't HTTP methods.
_NON_METHOD_KEYS = {"summary", "description", "parameters", "servers", "$ref"}


def generate_routes(out_dir: Path) -> Path:
    """Emit routes.md — the API inventory, from the OpenAPI spec.

    app.openapi() is the stable surface here: app.routes nests included
    routers as opaque _IncludedRouter objects rather than flat routes.
    """
    from app.main import app

    lines = [
        "# Routes",
        "",
        "The full machine-readable spec is served at `/openapi.json`.",
        "",
        "| Method | Path | Handler | Tags | Summary |",
        "|---|---|---|---|---|",
    ]
    for path, item in sorted(app.openapi()["paths"].items()):
        for method, op in sorted(item.items()):
            if method in _NON_METHOD_KEYS:
                continue
            handler = op.get("operationId", "—")
            tags = ", ".join(op.get("tags") or []) or "—"
            summary = op.get("summary") or ""
            lines.append(f"| {method.upper()} | `{path}` | `{handler}` | {tags} | {summary} |")
    return _write(out_dir, "api/routes.md", "\n".join(lines) + "\n")


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "out_dir",
        nargs="?",
        default="/docs/architecture",
        help="output directory (default: /docs/architecture, the mounted repo docs/)",
    )
    out_dir = Path(parser.parse_args().out_dir)

    _import_feature_models()
    for path in (generate_schema(out_dir), generate_erd(out_dir), generate_routes(out_dir)):
        print(f"wrote {path}")


if __name__ == "__main__":
    main()
